202	const DIRECT_LINK_RULE: ShowFn<DirectLinkElem> = |elem, _, _| {
203	    Ok(LinkElem::new(
204	        LinkTarget::Dest(Destination::Location(elem.loc)),
205	        elem.body.clone(),
206	    )
207	    .pack())
208	};
