214	const TITLE_RULE: ShowFn<TitleElem> = |elem, _, styles| {
215	    Ok(BlockElem::packed(
216	        HtmlElem::new(tag::h1)
217	            .with_body(Some(elem.resolve_body(styles).at(elem.span())?))
218	            .pack()
219	            .spanned(elem.span()),
220	    ))
221	};
