286	const FIGURE_CAPTION_RULE: ShowFn<FigureCaption> = |elem, engine, styles| {
287	    Ok(BlockElem::packed(
288	        HtmlElem::new(tag::figcaption)
289	            .with_body(Some(elem.realize(engine, styles)?))
290	            .pack()
291	            .spanned(elem.span()),
292	    ))
293	};
