922	    I: Iterator<Item = ResolvableGridItem<T>>,
923	    C: IntoIterator<Item = ResolvableGridChild<T, I>>,
924	    C::IntoIter: ExactSizeIterator,
925	{
926	    CellGridResolver {
927	        tracks,
928	        gutter,
929	        fill,
930	        align,
931	        inset,
932	        stroke,
933	        engine,
