1834	        //
1835	        // TODO(subfooters): take the last footer if it is at the end and
1836	        // backtrack through consecutive footers until the first one in the
1837	        // sequence is found. If there is no footer at the end, there are no
1838	        // headers to turn short-lived.
1839	        let mut consecutive_header_start =
1840	            footer.as_ref().map(|(_, _, f)| f.start).unwrap_or(row_amount);
1841	        let mut last_consec_level = 0;
1842	        for header in headers.iter_mut().rev() {
1843	            if header.range.end == consecutive_header_start
1844	                && header.level.get() >= last_consec_level
1845	            {
1846	                header.short_lived = true;
1847	            } else {
1848	                last_consec_level = header.level.get();
1849	            }
1850	
1851	            consecutive_header_start = header.range.start;
1852	        }
