1992	/// Given the existing range of a row group (header or footer), tries to expand
1993	/// it to fit the new cell placed inside it. If the newly-expanded row group
1994	/// would conflict with existing cells or other row groups, an error is
1995	/// returned. Otherwise, the new `start..end` range of rows in the row group is
1996	/// returned.
1997	fn expand_row_group(
1998	    resolved_cells: &[Option<Entry>],
1999	    group_range: Option<&Range<usize>>,
2000	    group_kind: RowGroupKind,
2001	    first_available_row: usize,
2002	    cell_y: usize,
2003	    rowspan: usize,
2004	    columns: usize,
2005	) -> HintedStrResult<Range<usize>> {
2006	    // Ensure each cell in a header or footer is fully contained within it by
2007	    // expanding the header or footer towards this new cell.
2008	    let (new_group_start, new_group_end) = group_range
2009	        .map_or((cell_y, cell_y + rowspan), |r| {
2010	            (r.start.min(cell_y), r.end.max(cell_y + rowspan))
2011	        });
2012	
2013	    // This check might be unnecessary with the loop below, but let's keep it
2014	    // here for full correctness.
2015	    //
2016	    // Quickly detect the case:
2017	    // y = 0 => occupied
2018	    // y = 1 => empty
2019	    // y = 2 => header
2020	    // and header tries to expand to y = 0 - invalid, as
2021	    // 'y = 1' is the earliest row it can occupy.
2022	    if new_group_start < first_available_row {
2023	        bail!(
2024	            "cell would cause {} to expand to non-empty row {}",
2025	            group_kind.name(),
2026	            first_available_row.saturating_sub(1);
2027	            hint: "try moving its cells to available rows";
2028	        );
2029	    }
2030	
2031	    let new_rows =
2032	        group_range.map_or((new_group_start..new_group_end).chain(0..0), |r| {
2033	            // NOTE: 'r.end' is one row AFTER the row group's last row, so it
2034	            // makes sense to check it if 'new_group_end > r.end', that is, if
2035	            // the row group is going to expand. It is NOT a duplicate check,
2036	            // as we hadn't checked it before (in a previous run, it was
2037	            // 'new_group_end' at the exclusive end of the range)!
2038	            //
2039	            // NOTE: To keep types the same, we have to always return
2040	            // '(range).chain(range)', which justifies chaining an empty
2041	            // range above.
2042	            (new_group_start..r.start).chain(r.end..new_group_end)
2043	        });
2044	
2045	    // The check above isn't enough, however, even when the header is expanding
2046	    // upwards, as it might expand upwards towards an occupied row after the
2047	    // first empty row, e.g.
2048	    //
2049	    // y = 0 => occupied
2050	    // y = 1 => empty (first_available_row = 1)
2051	    // y = 2 => occupied
2052	    // y = 3 => header
2053	    //
2054	    // Here, we should bail if the header tries to expand upwards, regardless
2055	    // of the fact that the conflicting row (y = 2) comes after the first
2056	    // available row.
2057	    //
2058	    // Note that expanding upwards is only possible when row-positioned cells
2059	    // are specified, in one of the following cases:
2060	    //
2061	    // 1. We place e.g. 'table.cell(y: 3)' followed by 'table.cell(y: 2)'
2062	    // (earlier row => upwards);
2063	    //
2064	    // 2. We place e.g. 'table.cell(y: 3)' followed by '[a]' (auto-pos cell
2065	    // favors 'first_available_row', so the header tries to expand upwards to
2066	    // place the cell at 'y = 1' and conflicts at 'y = 2') or
2067	    // 'table.cell(x: 1)' (same deal).
2068	    //
2069	    // Of course, we also need to check for downward expansion as usual as
2070	    // there could be a non-empty row below the header, but the upward case is
2071	    // highlighted as it was checked separately before (and also to explain
2072	    // what kind of situation we are preventing with this check).
2073	    //
2074	    // Note that simply checking for non-empty rows like below not only
2075	    // prevents conflicts with top-level cells (outside of headers and
2076	    // footers), but also prevents conflicts with other headers or footers,
2077	    // since we have an invariant that even empty headers and footers must
2078	    // contain at least one 'Some(...)' position in 'resolved_cells'. More
2079	    // precisely, each header and footer has at least one 'Some(...)' cell at
2080	    // 'group_range.start' and at 'group_range.end - 1' - non-empty headers and
2081	    // footers don't span any unnecessary rows. Therefore, we don't have to
2082	    // loop over headers and footers, only check if the new rows are empty.
2083	    for new_y in new_rows {
2084	        if let Some(new_row @ [_non_empty, ..]) = resolved_cells
2085	            .get(new_y * columns..)
2086	            .map(|cells| &cells[..columns.min(cells.len())])
2087	        {
2088	            if new_row.iter().any(Option::is_some) {
2089	                bail!(
2090	                    "cell would cause {} to expand to non-empty row {new_y}",
2091	                    group_kind.name();
2092	                    hint: "try moving its cells to available rows";
2093	                )
2094	            }
2095	        } else {
2096	            // Received 'None' or an empty slice, so we are expanding the
2097	            // header or footer into new rows, which is always valid and cannot
2098	            // conflict with existing cells. (Note that we only resize
2099	            // 'resolved_cells' after this function is called, so, if this
2100	            // header or footer is at the bottom of the table so far, this loop
2101	            // will end quite early, regardless of where this cell was placed
2102	            // or of its rowspan value.)
2103	            break;
2104	        }
2105	    }
2106	
2107	    Ok(new_group_start..new_group_end)
2108	}
2109	
2110	/// Check if a cell's fixed row would conflict with a header or footer.
2111	fn check_for_conflicting_cell_row(
2112	    header_rows: &SmallBitSet,
2113	    headers: &[Repeatable<Header>],
2114	    footer: Option<&(usize, Span, Footer)>,
2115	    cell_y: usize,
2116	    rowspan: usize,
2117	) -> HintedStrResult<()> {
2118	    if !headers.is_empty()
2119	        && let Some(row) =
2120	            (cell_y..cell_y + rowspan).find(|&row| header_rows.contains(row))
2121	    {
2122	        bail!(
2123	            "cell would conflict with header also spanning row {row}";
2124	            hint: "try moving the cell or the header";
2125	        );
2126	    }
2127	
2128	    // NOTE: y + rowspan >, not >=, footer.start, to check if the rowspan
2129	    // enters the footer. For example, consider a rowspan of 1: if
2130	    // `y + 1 = footer.start` holds, that means `y < footer.start`, and it
2131	    // only occupies one row (`y`), so the cell is actually not in
2132	    // conflict.
2133	    if let Some((_, _, footer)) = footer
2134	        && cell_y < footer.end
2135	        && cell_y + rowspan > footer.start
2136	    {
2137	        let row = (cell_y..cell_y + rowspan)
2138	            .find(|row| (footer.start..footer.end).contains(row))
2139	            .unwrap();
2140	
2141	        bail!(
2142	            "cell would conflict with footer also spanning row {row}";
2143	            hint: "try reducing the cell's rowspan or moving the footer";
2144	        );
2145	    }
2146	
2147	    Ok(())
2148	}
2149	
2150	/// Given a cell's requested x and y, the vector with the resolved cell
2151	/// positions, the `auto_index` counter (determines the position of the next
2152	/// `(auto, auto)` cell) and the amount of columns in the grid, returns the
2153	/// final index of this cell in the vector of resolved cells.
2154	///
2155	/// The `first_available_row` parameter is used by headers and footers to
2156	/// indicate the first empty row available. Any rows before those should
2157	/// not be picked by cells with `auto` row positioning, since headers and
2158	/// footers occupy entire rows, and may not conflict with cells outside them.
2159	#[expect(clippy::too_many_arguments)]
2160	fn resolve_cell_position(
2161	    cell_x: Smart<usize>,
2162	    cell_y: Smart<usize>,
2163	    colspan: usize,
2164	    rowspan: usize,
2165	    header_rows: &SmallBitSet,
2166	    headers: &[Repeatable<Header>],
2167	    footer: Option<&(usize, Span, Footer)>,
2168	    resolved_cells: &[Option<Entry>],
2169	    auto_index: &mut usize,
2170	    first_available_row: usize,
2171	    columns: usize,
2172	    in_row_group: bool,
2173	) -> HintedStrResult<usize> {
2174	    // Translates a (x, y) position to the equivalent index in the final cell vector.
2175	    // Errors if the position would be too large.
2176	    let cell_index = |x, y: usize| {
2177	        y.checked_mul(columns)
2178	            .and_then(|row_index| row_index.checked_add(x))
2179	            .ok_or_else(|| HintedString::from(eco_format!("cell position too large")))
2180	    };
2181	    match (cell_x, cell_y) {
2182	        // Fully automatic cell positioning. The cell did not
2183	        // request a coordinate.
2184	        (Smart::Auto, Smart::Auto) => {
2185	            // Let's find the first available position starting from the
2186	            // automatic position counter, searching in row-major order.
2187	            // Note that the counter ignores any cells with fixed positions,
2188	            // but automatically-positioned cells will avoid conflicts by
2189	            // simply skipping existing cells, headers and footers.
2190	            let resolved_index = find_next_available_position(
2191	                header_rows,
2192	                footer,
2193	                resolved_cells,
2194	                columns,
2195	                *auto_index,
2196	                false,
2197	            )?;
2198	
2199	            // Ensure the next cell with automatic position will be
2200	            // placed after this one (maybe not immediately after).
2201	            //
2202	            // The calculation below also affects the position of the upcoming
2203	            // automatically-positioned lines, as they are placed below
2204	            // (horizontal lines) or to the right (vertical lines) of the cell
2205	            // that would be placed at 'auto_index'.
2206	            *auto_index = if colspan == columns {
2207	                // The cell occupies all columns, so no cells can be placed
2208	                // after it until all of its rows have been spanned.
2209	                resolved_index + colspan * rowspan
2210	            } else {
2211	                // The next cell will have to be placed at least after its
2212	                // spanned columns.
2213	                resolved_index + colspan
2214	            };
2215	
2216	            Ok(resolved_index)
2217	        }
2218	        // Cell has chosen at least its column.
2219	        (Smart::Custom(cell_x), cell_y) => {
2220	            if cell_x >= columns {
2221	                return Err(HintedString::from(eco_format!(
2222	                    "cell could not be placed at invalid column {cell_x}"
2223	                )));
2224	            }
2225	            if let Smart::Custom(cell_y) = cell_y {
2226	                // Cell has chosen its exact position.
2227	                //
2228	                // Ensure it doesn't conflict with an existing header or
2229	                // footer (but only if it isn't already in one, otherwise there
2230	                // will already be a separate check).
2231	                if !in_row_group {
2232	                    check_for_conflicting_cell_row(
2233	                        header_rows,
2234	                        headers,
2235	                        footer,
2236	                        cell_y,
2237	                        rowspan,
2238	                    )?;
2239	                }
2240	
2241	                cell_index(cell_x, cell_y)
2242	            } else {
2243	                // Cell has only chosen its column.
2244	                // Let's find the first row which has that column available.
2245	                // If in a header or footer, start searching by the first empty
2246	                // row / the header or footer's first row (specified through
2247	                // 'first_available_row'). Otherwise, start searching at the
2248	                // first row.
2249	                let initial_index = cell_index(cell_x, first_available_row)?;
2250	
2251	                // Try each row until either we reach an absent position at the
2252	                // requested column ('Some(None)') or an out of bounds position
2253	                // ('None'), in which case we'd create a new row to place this
2254	                // cell in.
2255	                find_next_available_position(
2256	                    header_rows,
2257	                    footer,
2258	                    resolved_cells,
2259	                    columns,
2260	                    initial_index,
2261	                    true,
2262	                )
2263	            }
2264	        }
2265	        // Cell has only chosen its row, not its column.
2266	        (Smart::Auto, Smart::Custom(cell_y)) => {
2267	            // Ensure it doesn't conflict with an existing header or
2268	            // footer (but only if it isn't already in one, otherwise there
2269	            // will already be a separate check).
2270	            if !in_row_group {
2271	                check_for_conflicting_cell_row(
2272	                    header_rows,
2273	                    headers,
2274	                    footer,
2275	                    cell_y,
2276	                    rowspan,
2277	                )?;
2278	            }
2279	
2280	            // Let's find the first column which has that row available.
2281	            let first_row_pos = cell_index(0, cell_y)?;
2282	            let last_row_pos = first_row_pos
2283	                .checked_add(columns)
2284	                .ok_or_else(|| eco_format!("cell position too large"))?;
2285	
2286	            (first_row_pos..last_row_pos)
2287	                .find(|possible_index| {
2288	                    // Much like in the previous cases, we skip any occupied
2289	                    // positions until we either reach an absent position
2290	                    // (`Some(None)`) or an out of bounds position (`None`),
2291	                    // in which case we can just expand the vector enough to
2292	                    // place this cell. In either case, we found an available
2293	                    // position.
2294	                    !matches!(resolved_cells.get(*possible_index), Some(Some(_)))
2295	                })
2296	                .ok_or_else(|| {
2297	                    eco_format!(
2298	                        "cell could not be placed in row {cell_y} because it was full"
2299	                    )
2300	                })
2301	                .hint("try specifying your cells in a different order")
2302	        }
2303	    }
2304	}
2305	
2306	/// Finds the first available position after the initial index in the resolved
2307	/// grid of cells. Skips any non-absent positions (positions which already
2308	/// have cells specified by the user) as well as any headers and footers.
2309	///
2310	/// When `skip_rows` is true, one row is skipped on each iteration, preserving
2311	/// the column. That is used to find a position for a fixed column cell.
2312	#[inline]
2313	fn find_next_available_position(
2314	    header_rows: &SmallBitSet,
2315	    footer: Option<&(usize, Span, Footer)>,
2316	    resolved_cells: &[Option<Entry>],
2317	    columns: usize,
2318	    initial_index: usize,
2319	    skip_rows: bool,
2320	) -> HintedStrResult<usize> {
2321	    let mut resolved_index = initial_index;
2322	
2323	    loop {
2324	        if let Some(Some(_)) = resolved_cells.get(resolved_index) {
2325	            // Skip any non-absent cell positions (`Some(None)`) to
2326	            // determine where this cell will be placed. An out of
2327	            // bounds position (thus `None`) is also a valid new
2328	            // position (only requires expanding the vector).
2329	            if skip_rows {
2330	                // Skip one row at a time (cell chose its column, so we don't
2331	                // change it).
2332	                resolved_index =
2333	                    resolved_index.checked_add(columns).ok_or_else(|| {
2334	                        HintedString::from(eco_format!("cell position too large"))
2335	                    })?;
2336	            } else {
2337	                // Ensure we don't run unnecessary checks in the hot path
2338	                // (for fully automatically-positioned cells). Memory usage
2339	                // would become impractically large before this overflows.
2340	                resolved_index += 1;
2341	            }
2342	        } else if header_rows.contains(resolved_index / columns) {
2343	            // Skip header rows (can't place a cell inside it from outside it).
2344	            if skip_rows {
2345	                // Ensure the cell's chosen column is kept after the header.
2346	                resolved_index += columns;
2347	            } else {
2348	                // Skip to the start of the next row.
2349	                //
2350	                // Add 1 to resolved index to force moving to the next row if
2351	                // this is at the start of one. At the end of one, '+ 1'
2352	                // already pushes to the next one and 'next_multiple_of' does
2353	                // not modify it, so nothing bad happens then either.
2354	                resolved_index = (resolved_index + 1).next_multiple_of(columns);
2355	            }
2356	        } else if let Some((footer_end, _, footer)) = footer
2357	            && resolved_index >= footer.start * columns
2358	            && resolved_index < *footer_end * columns
2359	        {
2360	            // Skip footer, for the same reason.
2361	            resolved_index = *footer_end * columns;
2362	
2363	            if skip_rows {
2364	                // Ensure the cell's chosen column is kept after the
2365	                // footer.
2366	                resolved_index += initial_index % columns;
2367	            }
2368	        } else {
2369	            return Ok(resolved_index);
2370	        }
2371	    }
2372	}
2373	
2374	/// Computes the `y` of the next available empty row, given the auto index as
2375	/// an initial index for search, since we know that there are no empty rows
2376	/// before automatically-positioned cells, as they are placed sequentially.
2377	fn find_next_empty_row(
2378	    resolved_cells: &[Option<Entry>],
2379	    auto_index: usize,
2380	    columns: usize,
2381	) -> usize {
2382	    let mut resolved_index = auto_index.next_multiple_of(columns);
2383	    while resolved_cells
2384	        .get(resolved_index..resolved_index + columns)
2385	        .is_some_and(|row| row.iter().any(Option::is_some))
2386	    {
2387	        // Skip non-empty rows.
2388	        resolved_index += columns;
2389	    }
2390	
2391	    resolved_index / columns
2392	}
2393	
2394	/// Fully merged rows under the cell of latest auto index indicate rowspans
2395	/// occupying all columns, so we skip the auto index until the shortest rowspan
2396	/// ends, such that, in the resulting row, we will be able to place an
2397	/// automatically positioned cell - and, in particular, hlines under it. The
2398	/// idea is that an auto hline will be placed after the shortest such rowspan.
2399	/// Otherwise, the hline would just be placed under the first row of those
2400	/// rowspans and disappear (except at the presence of column gutter).
2401	fn skip_auto_index_through_fully_merged_rows(
2402	    resolved_cells: &[Option<Entry>],
2403	    auto_index: &mut usize,
2404	    columns: usize,
2405	) {
2406	    // If the auto index isn't currently at the start of a row, that means
2407	    // there's still at least one auto position left in the row, ignoring
2408	    // cells with manual positions, so we wouldn't have a problem in placing
2409	    // further cells or, in this case, hlines here.
2410	    if *auto_index % columns == 0 {
2411	        while resolved_cells
2412	            .get(*auto_index..*auto_index + columns)
2413	            .is_some_and(|row| {
2414	                row.iter().all(|entry| matches!(entry, Some(Entry::Merged { .. })))
2415	            })
2416	        {
2417	            *auto_index += columns;
2418	        }
2419	    }
2420	}
